import{_ as n,l,o as e,c as i,v as t,p as o,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"可测性设计与扫描链","description":"","frontmatter":{"title":"可测性设计与扫描链","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dft-scan-chain.md","filePath":"cs/dft-scan-chain.md","lastUpdated":1789023840000}'),h={name:"cs/dft-scan-chain.md"};function A(p,a,T,_,F,u){const s=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="可测性设计与扫描链" tabindex="-1">可测性设计与扫描链 <a class="header-anchor" href="#可测性设计与扫描链" aria-label="Permalink to &quot;可测性设计与扫描链&quot;">​</a></h1><div class="epigraph"><p>封装之后没有探针扎到每个触发器；把 FF 串成移位寄存器，测试仪才能移入向量、移出响应，判断组合逻辑是否粘死。</p><footer>—— 据 Bushnell and Agrawal, Essentials of Electronic Testing；IEEE Std 1149.1（JTAG）；Weste and Harris, CMOS VLSI Design 整理</footer></div><p><a href="/cs/formal-equivalence">上一课</a>保证网表与 RTL 一致，不保证<strong>硅</strong>无缺陷。<a href="/cs/moore-law-economics">摩尔经济学</a>把测试成本算进单价。缺口是 <strong>DFT</strong>：扫描链把触发器变成可控可观，否则自动测试仪（ATE）够不着内部节点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定故障（stuck-at）模型：某网恒 0/1。要激活故障并传播到可观察点。全组合电路还可用输入直接控；时序电路状态空间太大。扫描：每只 FF 加 MUX，测试模式时 D 来自上一只 FF 的 Q，链成移位寄存器。缺口不是再做 LEC，而是这套测试结构如何插入、如何与功能时钟共存。</p><p>IEEE 1149.1 JTAG 提供芯片级 TAP，边界扫描测引脚与板级互连；内部扫描是同一思想往里走。</p><h3 id="扫描不是「功能复位」" tabindex="-1">扫描不是「功能复位」 <a class="header-anchor" href="#扫描不是「功能复位」" aria-label="Permalink to &quot;扫描不是「功能复位」&quot;">​</a></h3><p>扫描移位时状态无功能含义，翻转率高、功耗大，须遵守测试功耗预算。功能复位树在测试模式可能被旁路。把扫描使能当复位，量产测试会破坏芯片或给出假失败。</p><p><span class="marginnote">Bushnell/Agrawal 是测试教材。1149.1 是边界扫描标准。Weste/Harris 有扫描 FF 电路。本课不背全部故障模型（转换延迟故障点名即可）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>综合后插入扫描 FF 与链。ATE：scan-in 一向量，脉冲一次功能捕获，scan-out。ATPG 生成向量。约束：扫描链时钟、锁存器电平敏感扫描（LSSD）是另一风格。与 <a href="/cs/sta">STA</a>：扫描移位路径有自己的时序，常更慢，单独约束。</p>',11)),(e(),o(E,null,{default:r(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF%5B%22%E5%8A%9F%E8%83%BD%20FF%22%5D%20--%3E%20MUX%5B%22%E6%B5%8B%E8%AF%95%20MUX%22%5D%0A%20%20MUX%20--%3E%20CHAIN%5B%22%E6%89%AB%E6%8F%8F%E9%93%BE%22%5D%0A%20%20CHAIN%20--%3E%20ATE%5B%22%E7%A7%BB%E5%85%A5%20%2F%20%E6%8D%95%E8%8E%B7%20%2F%20%E7%A7%BB%E5%87%BA%22%5D%0A%20%20ATE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ABIST%20%E6%8A%8A%20ATE%20%E6%90%AC%E8%BF%9B%E8%8A%AF%E7%89%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>算术单元的宽乘法器组合锥正是 ATPG 的负担；测试点插入可提高覆盖。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课 BIST 用片上图案生成器减少 ATE 数据量。扫描改变网表，必须再 LEC（功能模式 scan-enable=0）。时钟门控在测试中强制开。复位与扫描冲突由 DFT 规范定义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写模拟 BIST、不把系统级软件测试当 DFT。不讨论故障定位的软件算法细节。不进入封装探针卡机械。</p><p>后课默认：量产数字测试依赖扫描链把 FF 串起来；JTAG 管边界；内部还有 BIST。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>封装后靠扫描移位控/观内部 FF。</li><li>插入 MUX 改网表，功能模式须再等价检查。</li><li>测试功耗与扫描时序单独约束。</li><li>出处：Bushnell and Agrawal；IEEE 1149.1；Weste and Harris。</li></ul>',8))])}const m=n(h,[["render",A]]);export{f as __pageData,m as default};
